  `item_time` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `amulet` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `achievement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `studying` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `time_played` int NOT NULL DEFAULT 0,
  `type_trainning` tinyint NOT NULL DEFAULT 0,
  `online` tinyint NOT NULL DEFAULT 0,
  `time_at_split_fusion` bigint NOT NULL DEFAULT 0,
  `head2` int NOT NULL DEFAULT -1,
  `body` int NOT NULL DEFAULT -1,
  `leg` int NOT NULL DEFAULT -1,
  `collection_book` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `count_number_of_specialskill_changes` int NOT NULL DEFAULT 0,
  `special_skill` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `total_gold_bar` int NULL DEFAULT 0,
  `reset_time` timestamp NOT NULL DEFAULT current_timestamp,
  `login_time` timestamp NULL DEFAULT NULL,
  `logout_time` timestamp NULL DEFAULT NULL,
  `create_time` timestamp NOT NULL DEFAULT current_timestamp,
  `base_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `dataDHVT23` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `thoivang` int NOT NULL DEFAULT 0,
  `drop_item` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `point_bo_mong` int NULL DEFAULT 0 COMMENT 'Điểm tích lũy Bò Mộng',
  `count_nhiem_vu_bo_mong` int NULL DEFAULT 0 COMMENT 'Số nhiệm vụ đã làm hôm nay',
