INSERT INTO `nr_task` VALUES (22, 'Nhiệm vụ chạm trán Rôbốt sát thủ lần 1 (22)', '[\"Hãy đến thành phố phía Nam, đảo Balê\r\nhoặc Cao nguyên tìm gặp Rôbốt sát thủ\r\nđể tiêu diệt\",\"Hãy đến thành phố phía Nam, đảo Balê\r\nhoặc Cao nguyên tìm gặp Rôbốt sát thủ\r\nđể tiêu diệt\",\"Hãy đến thành phố phía Nam, đảo Balê\r\nhoặc Cao nguyên tìm gặp Rôbốt sát thủ\r\nđể tiêu diệt\"]', '[[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"],[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"],[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"]]', '[-1,-1,1,1,500,-1]', '[[37,-1,-1,-1,-1,37],[37,-1,-1,-1,-1,37],[37,-1,-1,-1,-1,37]]', '[[102,93,-1,-1,-1,102],[102,93,-1,-1,-1,102],[102,93,-1,-1,-1,102]]', '[[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"],[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"],[\"Tìm gặp bunma tại tương lai\",\"Đến điểm hẹn tìm Rôbốt sát thủ\",\"Tiêu diệt Android 19\",\"Tiêu diệt Dr.Kore\",\"Tiêu diệt Xên con cấp 3\",\"Trả nhiệm vụ cho Bunma\"]]', 150000, 150000, 0, 0, 0);
