INSERT INTO `nr_task` VALUES (26, 'Cuộc dạo chơi của Xên (26)', '[\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\",\r\n\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\",\r\n\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\"]', '[[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"],[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"],[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"]]\r\n', '[50,-1,7,1,-1]', '[[-1,-1,-1,-1,37],[-1,-1,-1,-1,37],[-1,-1,-1,-1,37]]', '[[-1,-1,-1,-1,102],[-1,-1,-1,-1,102],[-1,-1,-1,-1,102]]', '[[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"],[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"],[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"]]', 150000, 150000, 0, 0, 0);
